function generateFPSMap(canvasId) {
    const canvas = document.getElementById(canvasId);
    canvas.width = 500;
    canvas.height = 500;
    const ctx = canvas.getContext('2d');
    const N = 500;
    const occupancy = new Uint8Array(N * N);
    const visited = new Uint8Array(N * N);
    const roomCount = 8;
    const maxAttempts = 20;
    const roomMinSize = 70;
    const roomMaxSize = 150;
    const spawnCount = 6;
    const weaponCount = 6;

    function randomInt(min, max) {
        return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    function placeRooms() {
        const rooms = [];
        let attempts = 0;
        while (rooms.length < roomCount && attempts < 1000) {
            const w = randomInt(roomMinSize, roomMaxSize);
            const h = randomInt(roomMinSize, roomMaxSize);
            const x = randomInt(0, N - w);
            const y = randomInt(0, N - h);
            let overlap = false;
            for (const r of rooms) {
                if (x < r.x + r.w && x + w > r.x && y < r.y + r.h && y + h > r.y) {
                    overlap = true;
                    break;
                }
            }
            if (!overlap) {
                rooms.push({x, y, w, h});
                for (let i = x; i < x + w; i++) {
                    for (let j = y; j < y + h; j++) {
                        occupancy[j * N + i] = 1;
                    }
                }
            }
            attempts++;
        }
        return rooms;
    }

    function connectRooms(rooms) {
        for (let i = 0; i < rooms.length - 1; i++) {
            const a = rooms[i];
            const b = rooms[i + 1];
            const ax = a.x + Math.floor(a.w / 2);
            const ay = a.y + Math.floor(a.h / 2);
            const bx = b.x + Math.floor(b.w / 2);
            const by = b.y + Math.floor(b.h / 2);
            if (randomInt(0, 1) === 0) {
                carveHorizontal(ax, bx, ay);
                carveVertical(ax, bx, ay, by);
            } else {
                carveVertical(ax, bx, ay, by);
                carveHorizontal(ax, bx, by);
            }
        }
    }

    function carveHorizontal(x1, x2, y) {
        const min = Math.min(x1, x2);
        const max = Math.max(x1, x2);
        for (let x = min; x <= max; x++) {
            occupancy[y * N + x] = 1;
        }
    }

    function carveVertical(x1, x2, y1, y2) {
        const min = Math.min(y1, y2);
        const max = Math.max(y1, y2);
        for (let y = min; y <= max; y++) {
            occupancy[y * N + x1] = 1;
        }
    }

    function floodFill(startX, startY) {
        visited.fill(0);
        const stack = [];
        stack.push(startX * N + startY);
        while (stack.length) {
            const idx = stack.pop();
            if (visited[idx]) continue;
            visited[idx] = 1;
            const x = idx % N;
            const y = Math.floor(idx / N);
            if (x > 0 && occupancy[idx - 1] && !visited[idx - 1]) stack.push(idx - 1);
            if (x < N - 1 && occupancy[idx + 1] && !visited[idx + 1]) stack.push(idx + 1);
            if (y > 0 && occupancy[idx - N] && !visited[idx - N]) stack.push(idx - N);
            if (y < N - 1 && occupancy[idx + N] && !visited[idx + N]) stack.push(idx + N);
        }
    }

    function allReachable(rooms) {
        floodFill(0, 0);
        for (const r of rooms) {
            for (let i = r.x; i < r.x + r.w; i++) {
                for (let j = r.y; j < r.y + r.h; j++) {
                    if (occupancy[j * N + i] && !visited[j * N + i]) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    function placeItems(count, color) {
        const items = [];
        let attempts = 0;
        while (items.length < count && attempts < 1000) {
            const x = randomInt(0, N - 1);
            const y = randomInt(0, N - 1);
            if (occupancy[y * N + x] && !visited[y * N + x]) {
                items.push({x, y});
            }
            attempts++;
        }
        return items;
    }

    function draw() {
        ctx.fillStyle = 'black';
        ctx.clearRect(0, 0, N, N);
        // draw floor
        ctx.fillStyle = 'gray';
        for (let i = 0; i < N * N; i++) {
            if (occupancy[i]) {
                const x = i % N;
                const y = Math.floor(i / N);
                ctx.fillRect(x, y, 1, 1);
            }
        }
        // spawn points
        for (const p of spawnPoints) {
            ctx.fillStyle = 'green';
            ctx.beginPath();
            ctx.arc(p.x, p.y, 3, 0, 2 * Math.PI);
            ctx.fill();
        }
        // weapon pickups
        for (const p of weaponPoints) {
            ctx.fillStyle = 'red';
            ctx.beginPath();
            ctx.arc(p.x, p.y, 3, 0, 2 * Math.PI);
            ctx.fill();
        }
        // legend
        ctx.fillStyle = 'rgba(0,0,0,0.7)';
        ctx.fillRect(10, N - 80, 120, 70);
        ctx.fillStyle = 'white';
        ctx.font = '12px Arial';
        ctx.fillText('Legend', 15, N - 60);
        ctx.fillStyle = 'black';
        ctx.fillRect(15, N - 45, 10, 10);
        ctx.fillStyle = 'gray';
        ctx.fillRect(15, N - 30, 10, 10);
        ctx.fillStyle = 'green';
        ctx.fillRect(15, N - 15, 10, 10);
        ctx.fillStyle = 'red';
        ctx.fillRect(15, N, 10, 10);
        ctx.fillStyle = 'white';
        ctx.fillText('Walls', 30, N - 36);
        ctx.fillText('Floors', 30, N - 21);
        ctx.fillText('Spawn', 30, N - 6);
        ctx.fillText('Weapon', 30, N + 9);
    }

    function generate() {
        let success = false;
        for (let attempt = 0; attempt < maxAttempts && !success; attempt++) {
            occupancy.fill(0);
            const rooms = placeRooms();
            connectRooms(rooms);
            if (allReachable(rooms)) {
                spawnPoints = placeItems(spawnCount, 'green');
                weaponPoints = placeItems(weaponCount, 'red');
                success = true;
            }
        }
        draw();
    }

    let spawnPoints, weaponPoints;

    // button
    const btn = document.createElement('button');
    btn.textContent = 'Generate New Map';
    btn.style.position = 'absolute';
    btn.style.left = canvas.offsetLeft + 'px';
    btn.style.top = canvas.offsetTop + canvas.height + 10 + 'px';
    btn.style.width = '150px';
    document.body.appendChild(btn);
    btn.addEventListener('click', generate);
    generate();
}
